node <<'EOF'
const ts = require('typescript');
const path = require('path');
const configPath = path.resolve('tsconfig.json');
const read = ts.readConfigFile(configPath, ts.sys.readFile);
if (read.error) {
  console.error('CONFIG_READ_ERROR', ts.flattenDiagnosticMessageText(read.error.messageText, '\n'));
  process.exit(2);
}
const parsed = ts.parseJsonConfigFileContent(read.config, ts.sys, path.dirname(configPath));
if (parsed.errors && parsed.errors.length) {
  console.error('CONFIG_PARSE_ERRORS');
  for (const e of parsed.errors) {
    console.error(ts.flattenDiagnosticMessageText(e.messageText, '\n'));
  }
}
const program = ts.createProgram({ rootNames: parsed.fileNames, options: parsed.options });
const rels = [
  'src/i18n/locale/en.ts',
  'src/i18n/locale/zh.ts',
  'src/i18n/locale/zh_tw.ts',
  'src/screens/splash-screen/splash-screen.tsx',
];
let total = 0;
for (const rel of rels) {
  const abs = path.resolve(rel);
  const sf = program.getSourceFile(abs);
  if (!sf) {
    console.log(`MISSING_SOURCE ${rel}`);
    total++;
    continue;
  }
  const diags = [
    ...program.getSyntacticDiagnostics(sf),
    ...program.getSemanticDiagnostics(sf),
    ...program.getSuggestionDiagnostics(sf),
  ];
  console.log(`FILE ${rel} count=${diags.length}`);
  for (const d of diags) {
    const pos = d.start != null ? sf.getLineAndCharacterOfPosition(d.start) : { line: 0, character: 0 };
    const cat = ts.DiagnosticCategory[d.category];
    console.log(`${rel}:${pos.line + 1}:${pos.character + 1} ${cat} TS${d.code} ${ts.flattenDiagnosticMessageText(d.messageText, ' ')}`);
    total++;
  }
}
console.log(`TOTAL ${total}`);
EOF

