  const sf = program.getSourceFile(t);
  if (!sf) { console.log('NOT IN PROGRAM', t); continue; }
  const fmt = d => {
    const pos = d.file && d.start != null ? d.file.getLineAndCharacterOfPosition(d.start) : null;
    return `${path.relative(process.cwd(), t)}:${pos ? pos.line + 1 : '?'} TS${d.code} ${ts.flattenDiagnosticMessageText(d.messageText, ' ')}`;
  };
  const syn = program.getSyntacticDiagnostics(sf);
  const sem = program.getSemanticDiagnostics(sf);
  const sug = program.getSuggestionDiagnostics(sf);
  console.log(`== ${path.relative(process.cwd(), t)} syntactic=${syn.length} semantic=${sem.length} suggestion=${sug.length}`);
  [...syn, ...sem].forEach(d => console.log('  ERR ' + fmt(d)));
  sug.forEach(d => console.log('  SUG ' + fmt(d)));
}
EOF
